INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65341123', 65341123, 'analyze_legacy', 'Provinsi Kalimantan Timur', 'provinsi', 'Dinas Kelautan Dan Perikanan', 'Kegiatan Review Materi Teknis Perairan Pesisir dan Pulau-pulau kecil', 'Barang', 'E-Purchasing', 'Kalimantan Timur, Samarinda (Kota)', 14544000, 'February 2025', 'APBD', 1, 1, '1 Paket', 'Wilayah pesisir dan laut Provinsi Kalimantan Timur memiliki peranan strategis dalam mendukung pembangunan ekonomi daerah sekaligus menjaga keseimbangan ekosistem laut. Berbagai aktivitas seperti perikanan, transportasi laut, pelabuhan, wisata bahari, industri, hingga eksplorasi sumberdaya alam, membutuhkan pengaturan yang jelas agar pemanfaatan ruang laut berjalan tertib, berkelanjutan, dan sesuai peruntukan. Sebagai tindak lanjut dari Peraturan Daerah Provinsi Kalimantan Timur Nomor 1 Tahun 2023 tentang Rencana Tata Ruang Wilayah (RTRW) Provinsi Kalimantan Timur Tahun 2023&ndash;2042, pemerintah daerah berkewajiban melakukan penataan ruang laut secara sistematis, termasuk mencatat dan mengadministrasikan perizinan berusaha di wilayah pesisir dan laut. Hal ini menjadi sangat penting karena penyusunan RTRW tersebut telah mengintegrasikan Materi Teknis Perairan Pesisir sebagaimana diamanatkan dalam Peraturan Menteri Kelautan dan Perikanan Nomor 28 Tahun 2021 tentang Penyelenggaraan', 'Penjilidan kegiatan,Makan siang,snack(kudapan)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2101388);
